// Refuse an empty answer, so a Shopify hiccup can never mark every location inactive.
const nodes = $('Get locations').first().json.data?.locations?.nodes || [];
if (!nodes.length) throw new Error('Shopify returned no locations; nothing changed');
const known = $('Read stock locations').all().map(i => i.json).filter(r => r.location_id);
const ids = new Set(nodes.map(n => n.id));
const rows = nodes.map(n => ({ location_id: n.id, name: n.name, is_active: n.isActive, fulfills_online_orders: n.fulfillsOnlineOrders }));
for (const r of known) if (!ids.has(r.location_id)) rows.push({ location_id: r.location_id, name: r.name, is_active: false, fulfills_online_orders: false });
return rows.map(json => ({ json }));

// One price list row -> one offer row. Column names come from settings.
const s = $('Ingest settings').first().json;
const c = s.columns;
const text = v => (v ?? '').toString().trim();
const num = v => {
  let t = text(v).replace(/[^0-9.,\-]/g, '');
  if (/,\d{1,2}$/.test(t)) t = t.replace(/\./g, '').replace(',', '.'); // "1.234,50" -> 1234.50
  else t = t.replace(/,/g, '');                                       // "1,234.50" -> 1234.50
  const n = parseFloat(t); return Number.isFinite(n) ? n : null;
};
const qty = v => { const n = parseInt(text(v).replace(/[^0-9]/g, ''), 10); return Number.isFinite(n) ? n : 0; }; // "20+" -> 20, "CALL" -> 0
const gone = v => s.discontinued_values.includes(text(v).toLowerCase());
return $input.all().map(({ json: r }) => {
  let cost = num(r[c.cost]);
  if (cost !== null && s.cost_includes_tax) cost = +(cost / (1 + s.tax_rate)).toFixed(2);
  return { json: {
    source: s.source_name, source_sku: text(r[c.source_sku]),
    mpn: text(r[c.mpn]), gtin: text(r[c.gtin]).replace(/\D/g, ''),
    brand: text(r[c.brand]), title: text(r[c.title]), category_raw: text(r[c.category]),
    cost, shipping_cost: s.shipping_per_unit || 0, rrp: num(r[c.rrp]),
    stock: qty(r[c.stock]), image_url: text(r[c.image]),
    discontinued: c.discontinued ? gone(r[c.discontinued]) : false,
  } };
}).filter(i => i.json.source_sku);

// Hold the whole feed when it looks broken, so a bad file can't zero your store.
const s = $('Ingest settings').first().json;
const rows = $('Map price list').all().map(i => i.json).filter(r => r.source_sku);
const last = $('Last feed run').first().json || {};
const inStock = rows.filter(r => r.stock > 0).length;
const reasons = [];
if (!rows.length) reasons.push('the feed has no rows');
if (last.rows > 0 && rows.length < last.rows * (1 - s.max_feed_shrink))
  reasons.push(`the feed shrank from ${last.rows} to ${rows.length} rows`);
if (last.in_stock > 0 && inStock < last.in_stock * (1 - s.max_feed_shrink))
  reasons.push(`rows in stock fell from ${last.in_stock} to ${inStock}`);
return [{ json: {
  source: s.source_name, rows: rows.length, in_stock: inStock,
  status: reasons.length ? 'held' : 'ok', reason: reasons.join('; '),
  run_at: new Date().toISOString(),
} }];

// Write only what changed: new rows, changed rows, rows that came back, and rows that went missing.
const feed = $('Map price list').all().map(i => i.json).filter(r => r.source_sku);
const known = new Map($('Get offers for Ingest').all().map(i => i.json).filter(o => o.source_sku).map(o => [o.source_sku, o]));
const fields = ['mpn', 'gtin', 'brand', 'title', 'category_raw', 'cost', 'shipping_cost', 'rrp', 'stock', 'image_url', 'discontinued'];
const same = (a, b) => (a ?? '') === (b ?? '') || ((typeof a === 'number' || typeof b === 'number') && Number(a) === Number(b));
const now = new Date().toISOString();
const out = [], inFeed = new Set();
for (const r of feed) {
  inFeed.add(r.source_sku);
  const o = known.get(r.source_sku);
  if (!o || o.missing_since || fields.some(f => !same(r[f], o[f]))) out.push({ ...r, kind: 'seen', missing_since: null });
}
for (const [sku, o] of known)
  if (!inFeed.has(sku) && !o.missing_since) out.push({ kind: 'missing', id: o.id, source_sku: sku, missing_since: now });
return out.map(json => ({ json }));

// Skip any source whose feed has gone quiet or has nowhere to put its stock, and say so.
const s = $('Sync settings').first().json;
const offers = $('Get offers').all().map(i => i.json).filter(o => o.source && o.source_sku);
const locations = $('Get stock locations').all().map(i => i.json).filter(l => l.is_active && l.source);
const hours = d => (Date.now() - new Date(d).getTime()) / 36e5;

const newest = {};   // the last good feed run per source
for (const { json: r } of $('Get feed runs').all())
  if (r.source) newest[r.source] = Math.max(newest[r.source] || 0, new Date(r.run_at).getTime());
const sources = [...new Set([...Object.keys(newest), ...locations.map(l => l.source)])]
  .filter(src => offers.some(o => o.source === src));
const stale = sources.filter(src => !newest[src] || hours(newest[src]) > s.freshness_hours);
const unmapped = sources.filter(src => !locations.some(l => l.source === src));
const offline = locations.filter(l => !l.fulfills_online_orders).map(l => l.name);
const live = sources.filter(src => !stale.includes(src) && !unmapped.includes(src))
  .map(src => ({ source: src, location_id: locations.find(l => l.source === src).location_id }));
return [{ json: { live, stale, unmapped, offline, warn: stale.length + unmapped.length + offline.length > 0 } }];

