// One search per 50 SKUs, per source, carrying the location that source's stock lives in.
const { live } = $('Check the feeds').first().json;
const offers = $('Get offers').all().map(i => i.json);
const quote = k => 'sku:"' + String(k).replace(/["\\]/g, '').trim() + '"';
const out = [];
for (const { source, location_id } of live) {
  const keys = [...new Set(offers.filter(o => o.source === source)
    .flatMap(o => [o.mpn, o.source_sku]).filter(Boolean).map(k => String(k).trim()))];
  for (let i = 0; i < keys.length; i += 50)
    out.push({ json: { source, location_id, q: keys.slice(i, i + 50).map(quote).join(' OR ') } });
}
return out;

