// Remember which Shopify product each offer belongs to, so the Sweep lane can find it later.
const batches = $('Batch the lookups').all().map(i => i.json);
const key = (src, k) => src + '|' + String(k).trim().toUpperCase();
const offerFor = new Map();
for (const { json: o } of $('Get offers').all())
  for (const k of [o.source_sku, o.mpn]) if (k) offerFor.set(key(o.source, k), o);
const links = new Map();
$input.all().forEach((res, i) => {
  for (const v of res.json.data?.productVariants?.nodes || []) {
    const o = v.sku && offerFor.get(key(batches[i].source, v.sku));
    if (o && o.product_id !== v.product.id) links.set(o.id, { id: o.id, product_id: v.product.id });
  }
});
return [...links.values()].map(json => ({ json }));

// What each matched variant should hold at its source's location. Only differences are kept.
const s = $('Sync settings').first().json;
const batches = $('Batch the lookups').all().map(i => i.json);
const key = (src, k) => src + '|' + String(k).trim().toUpperCase();
const offerFor = new Map();
for (const { json: o } of $('Get offers').all())
  for (const k of [o.source_sku, o.mpn]) if (k) offerFor.set(key(o.source, k), o);

const levels = [], costs = [], continueSelling = [];
let archived = 0, untracked = 0;
const seen = new Set();
$input.all().forEach((res, i) => {           // one response per batch, in the same order
  const b = batches[i];
  for (const v of res.json.data?.productVariants?.nodes || []) {
    const o = v.sku && offerFor.get(key(b.source, v.sku));
    if (!o || seen.has(v.id)) continue;      // the search returned a near match, or a repeat
    seen.add(v.id);
    if (v.product.status === 'ARCHIVED') { archived++; continue; }
    if (!v.inventoryItem.tracked) { untracked++; continue; }
    if (v.inventoryPolicy === 'CONTINUE') continueSelling.push(v.product.title);

    const dropped = Boolean(o.missing_since);
    const target = o.discontinued || dropped ? 0 : Math.max(0, (o.stock || 0) - s.safety_stock);
    const level = v.inventoryItem.inventoryLevel;
    const current = level ? level.quantities[0].quantity : null;
    if (level ? current !== target : target > 0) levels.push({
      kind: 'level', item: v.inventoryItem.id, location: b.location_id, has_level: !!level,
      target, current, title: v.product.title, sku: v.sku,
      reason: o.discontinued ? 'discontinued' : dropped ? 'dropped from feed' : 'supplier stock',
    });

    const landed = o.cost > 0 ? +(o.cost + (o.shipping_cost || 0)).toFixed(2) : null;
    const unit = v.inventoryItem.unitCost ? Number(v.inventoryItem.unitCost.amount) : null;
    if (s.sync_cost && landed && (unit === null || Math.abs(unit - landed) >= 0.01))
      costs.push({ kind: 'cost', item: v.inventoryItem.id, cost: landed, title: v.product.title });
  }
});

// Batched mutations. Each write carries an idempotency key, so a retried request can't apply twice.
const q = v => JSON.stringify(String(v));
const run = String($execution.id);
const planned = levels.slice(0, s.max_changes);
const summary = { planned: planned.length, carried_over: levels.length - planned.length,
  costs_planned: costs.length, archived, untracked, continue_selling: continueSelling };
const out = [];
for (let b = 0; b < planned.length; b += s.batch_size) {
  const batch = planned.slice(b, b + s.batch_size);
  const acts = batch.filter(r => !r.has_level), sets = batch.filter(r => r.has_level);
  const parts = acts.map((r, i) => `a${i}: inventoryActivate(inventoryItemId: ${q(r.item)}, locationId: ${q(r.location)}, available: ${r.target}) @idempotent(key: ${q(run + '-a-' + b + '-' + i)}) { inventoryLevel { id } userErrors { field message } }`);
  if (sets.length) parts.push(`s: inventorySetQuantities(input: { name: "available", reason: "correction", quantities: [${sets.map(r => `{ inventoryItemId: ${q(r.item)}, locationId: ${q(r.location)}, quantity: ${r.target}, changeFromQuantity: null }`).join(', ')}] }) @idempotent(key: ${q(run + '-s-' + b)}) { userErrors { field message } }`);
  out.push({ json: { kind: 'level', acts, sets, mutation: `mutation { ${parts.join(' ')} }`, summary } });
}
for (let b = 0; b < costs.length; b += s.batch_size) {
  const rows = costs.slice(b, b + s.batch_size);
  const parts = rows.map((r, i) => `c${i}: inventoryItemUpdate(id: ${q(r.item)}, input: { cost: ${q(r.cost.toFixed(2))} }) { inventoryItem { id } userErrors { field message } }`);
  out.push({ json: { kind: 'cost', rows, mutation: `mutation { ${parts.join(' ')} }`, summary } });
}
return out.length ? out : [{ json: { kind: 'none', summary } }];

// One result per planned row. Shopify's errors are recorded here, not thrown, so one bad row doesn't stop the run.
const sent = $('Plan changes').all().map(i => i.json);
const msg = ue => (ue || []).map(e => e.message).join('; ') || null;
const results = [];
$input.all().forEach((res, i) => {
  const b = sent[i], d = res.json.data || {};
  const top = msg(res.json.errors) || (res.json.error ? String(res.json.error.message || res.json.error) : null);
  if (b.kind === 'level') {
    b.acts.forEach((r, n) => {
      const err = top || msg(d['a' + n]?.userErrors) || (d['a' + n]?.inventoryLevel ? null : 'no level returned');
      results.push({ ...r, ok: !err, error: err });
    });
    const setErr = b.sets.length ? (top || msg(d.s?.userErrors) || (d.s ? null : 'no response')) : null;
    b.sets.forEach(r => results.push({ ...r, ok: !setErr, error: setErr }));
  } else {
    b.rows.forEach((r, n) => {
      const err = top || msg(d['c' + n]?.userErrors) || (d['c' + n]?.inventoryItem ? null : 'no item returned');
      results.push({ ...r, ok: !err, error: err });
    });
  }
});
const p = sent[0].summary, lv = results.filter(r => r.kind === 'level'), cs = results.filter(r => r.kind === 'cost');
const summary = { ...p,
  levels_set: lv.filter(r => r.ok).length, zeroed: lv.filter(r => r.ok && r.target === 0).length,
  levels_failed: lv.filter(r => !r.ok).length, costs_set: cs.filter(r => r.ok).length,
  costs_failed: cs.filter(r => !r.ok).length,
  errors: [...new Set(results.filter(r => !r.ok).map(r => r.error))].slice(0, 5) };
return [{ json: { summary, results } }];

