={{ JSON.stringify({ channel: $('Sync settings').first().json.slack_log_channel, unfurl_links: false, text: (s => `Stock sync: ${s.levels_set} stock level${s.levels_set === 1 ? '' : 's'} updated (${s.zeroed} set to 0), ${s.costs_set} unit cost${s.costs_set === 1 ? '' : 's'} updated.`
  + (s.carried_over ? `\n${s.carried_over} more changes wait for the next run.` : '')
  + (s.continue_selling.length ? `\nStill selling at zero stock: ${s.continue_selling.slice(0, 5).join(', ')}` : '')
  + (s.levels_failed || s.costs_failed ? `\n:warning: ${s.levels_failed} levels and ${s.costs_failed} costs failed: ${s.errors.join('; ')}` : '')
)($json.summary) }) }}

