// Products whose every offer is marked discontinued, or missing from the feed for gone_days, not decided yet, oldest first.
const s = $('Sweep settings').first().json;
const days = d => (Date.now() - new Date(d).getTime()) / 864e5;
const queue = new Map($('Get retire queue').all().map(i => [i.json.product_id, i.json]));
const open = r => !r || !r.status || (r.status === 'snoozed' && new Date(r.snooze_until) <= new Date());
const byProduct = new Map();
for (const { json: o } of $('Get offers for Sweep').all()) {
  if (!o.product_id) continue;
  byProduct.set(o.product_id, [...(byProduct.get(o.product_id) || []), o]);
}
const picked = [...byProduct].map(([product_id, list]) => ({
    product_id,
    gone: list.every(o => o.discontinued || (o.missing_since && days(o.missing_since) >= s.gone_days)),
    gone_since: list.some(o => o.missing_since)   // when the last offer left the feed; null if only marked discontinued
      ? new Date(Math.max(...list.filter(o => o.missing_since).map(o => new Date(o.missing_since).getTime()))).toISOString() : null,
    skus: list.map(o => o.source + ' ' + o.source_sku),
    cost: list[0].cost,
  }))
  .filter(p => p.gone && open(queue.get(p.product_id)))
  .sort((a, b) => (a.gone_since || '9').localeCompare(b.gone_since || '9'))
  .slice(0, s.cards_per_run);
return picked.length ? [{ json: { ids: picked.map(p => p.product_id), picked } }] : [];

