// One card per product still ACTIVE in Shopify. The button value is the product ID and nothing else.
const s = $('Sweep settings').first().json;
const picked = new Map($('Pick candidates').first().json.picked.map(p => [p.product_id, p]));
const pt = text => ({ type: 'plain_text', text });
return ($json.data?.nodes || []).filter(p => p && p.status === 'ACTIVE').map(p => {
  const c = picked.get(p.id);

  const cols = p.collections.nodes;
  const best = cols.find(x => x.title.toLowerCase() === (p.productType || '').toLowerCase()) || cols[0];
  const redirect_to = best ? '/collections/' + best.handle : s.fallback_redirect;
  const admin = `https://${s.store_domain}/admin/products/${p.id.split('/').pop()}`;
  const when = c.gone_since
    ? `Last in the feed ${c.gone_since.slice(0, 10)} (${Math.floor((Date.now() - new Date(c.gone_since).getTime()) / 6048e5)} weeks ago)`
    : 'Marked discontinued in the feed';
  const blocks = [
    { type: 'header', text: pt('Dropped by your supplier') },
    { type: 'section', text: { type: 'mrkdwn', text: `*<${admin}|${p.title}>*\n${when}` } },
    { type: 'section', fields: [
      { type: 'mrkdwn', text: `*Your stock left*\n${p.totalInventory}` },
      { type: 'mrkdwn', text: `*Last cost*\n${c.cost == null ? 'n/a' : Number(c.cost).toFixed(2) + ' ' + s.currency}` },
      { type: 'mrkdwn', text: `*Feed SKU*\n${c.skus.join(', ')}` },
      { type: 'mrkdwn', text: `*Redirect to*\n${redirect_to}` },
    ] },
    { type: 'actions', elements: [
      { type: 'button', action_id: 'retire_redirect', style: 'danger', text: pt('Archive and redirect'), value: p.id,
        confirm: { title: pt('Archive this product?'), text: { type: 'mrkdwn', text: `Archives it and sends its page to ${redirect_to}. Nothing is deleted.` }, confirm: pt('Archive'), deny: pt('Cancel') } },
      { type: 'button', action_id: 'retire_keep', style: 'primary', text: pt('Keep the page'), value: p.id },
      { type: 'button', action_id: 'retire_snooze', text: pt(`Snooze ${s.snooze_days} days`), value: p.id },
    ] },
  ];
  return { json: { product_id: p.id, title: p.title, handle: p.handle, gone_since: c.gone_since, redirect_to, blocks,
    text: `Dropped by your supplier: ${p.title}` } };
});

const raw = (await this.helpers.getBinaryDataBuffer(0, 'data')).toString('utf8');
const h = $input.first().json.headers;
if (Math.abs(Date.now() / 1000 - Number(h['x-slack-request-timestamp'])) > 300) throw new Error('Stale request');
const field = raw.split('&').find(kv => kv.startsWith('payload=')) || ''; // no URLSearchParams in the Code node
const p = JSON.parse(decodeURIComponent(field.slice(8).replace(/\+/g, ' ')));
const a = p.actions[0];
return [{ json: { base: `v0:${h['x-slack-request-timestamp']}:${raw}`, expected: h['x-slack-signature'],
  action: a.action_id.replace('retire_', ''), product_id: a.value, user: p.user.username, channel: p.channel.id, ts: p.message.ts,
  blocks: (p.message.blocks || []).filter(b => b.type !== 'actions') } }];

