// Record a decision only when Shopify accepted every change. Snooze never touches Shopify.
const c = $('Parse click').first().json, s = $('Review settings').first().json;
const row = $('Get queue row').first().json;
const call = { redirect: 'Retire in Shopify', keep: 'Keep in Shopify' }[c.action];
const dry = Boolean(call && s.dry_run);
let ok = true, why = '', existing = false;
if (call && !dry) {
  const r = $(call).first().json;
  let errors = [...(r.errors || []), ...Object.values(r.data || {}).flatMap(x => (x && x.userErrors) || [])].map(e => e.message);
  existing = errors.some(m => /already been taken/i.test(m));   // a redirect for this URL already exists: keep it
  errors = errors.filter(m => !/already been taken/i.test(m));
  if (!r.data || errors.length) { ok = false; why = errors.join('; ') || (r.error && r.error.message) || 'no answer from Shopify'; }
}
const text = {
  redirect: existing ? ':file_cabinet: Archived (its URL already had a redirect, which stays)'
    : `:file_cabinet: Archived, and its page now redirects to ${row.redirect_to}`,
  keep: ':white_check_mark: Kept: the page stays live as sold out and won\'t be proposed again',
  snooze: `:zzz: Snoozed for ${s.snooze_days} days`,
}[c.action] + ` by @${c.user}`;
return [{ json: {
  save: ok && !dry, text,
  status: { redirect: 'retired', keep: 'kept', snooze: 'snoozed' }[c.action],
  snooze_until: c.action === 'snooze' ? new Date(Date.now() + s.snooze_days * 864e5).toISOString() : null,
  reply: dry ? 'Dry run: Shopify was not changed and nothing was recorded.' : `:warning: Not done: ${why}. The buttons stay on the card.`,
} }];
